    "ogHeadline": "AJ1 LOW OG\n\"SOMOS HISTORIAS\"",
    "ogAccent": "C8102E",
    "heroImage": "https://www.nicekicks.com/files/2026/10/iz4686-216-5-2-e1791583365212.jpg",
